components.css:
.ds-btn-primary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 44px;
  padding: 12px 24px;
  background-color: oklch(74% 0.175 65);
  color: oklch(17% 0.01 65);
  font-family: 'Albert Sans', ui-sans-serif, system-ui, sans-serif;
  font-size: 0.875rem;
  font-weight: 600;
  border: none;
  border-radius: 8px;
  cursor: pointer;
  transition: background-color 150ms cubic-bezier(0.25, 1, 0.5, 1), transform 150ms cubic-bezier(0.25, 1, 0.5, 1);
}
.ds-btn-primary:hover {
  filter: brightness(1.1);
}
.ds-btn-primary:focus-visible {
  outline: 2px solid oklch(74% 0.175 65 / 50%);
  outline-offset: 2px;
}
.ds-btn-primary:active {
  transform: scale(0.98);
  filter: brightness(0.95);
}
.ds-btn-primary:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}
@media (prefers-reduced-motion: reduce) {
  .ds-btn-primary {
    transition-duration: 0.01ms;
  }
}

.ds-btn-outline {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 44px;
  padding: 12px 24px;
  background-color: transparent;
  color: oklch(45% 0.014 65);
  font-family: 'Albert Sans', ui-sans-serif, system-ui, sans-serif;
  font-size: 0.875rem;
  font-weight: 600;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  border: 2px solid oklch(90% 0.008 65);
  border-radius: 8px;
  cursor: pointer;
  transition: color 150ms cubic-bezier(0.25, 1, 0.5, 1), background-color 150ms cubic-bezier(0.25, 1, 0.5, 1), border-color 150ms cubic-bezier(0.25, 1, 0.5, 1);
}
.ds-btn-outline:hover {
  border-color: oklch(60% 0.01 65);
  background-color: oklch(92% 0.006 65);
}
.ds-btn-outline:focus-visible {
  outline: 2px solid oklch(74% 0.175 65 / 50%);
  outline-offset: 2px;
}
.ds-btn-outline:active {
  transform: scale(0.98);
}
@media (prefers-reduced-motion: reduce) {
  .ds-btn-outline {
    transition-duration: 0.01ms;
  }
}

.ds-btn-ghost {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 44px;
  padding: 12px 24px;
  background-color: transparent;
  color: oklch(45% 0.014 65);
  font-family: 'Albert Sans', ui-sans-serif, system-ui, sans-serif;
  font-size: 0.875rem;
  font-weight: 500;
  border: none;
  border-radius: 8px;
  cursor: pointer;
  transition: color 150ms cubic-bezier(0.25, 1, 0.5, 1);
}
.ds-btn-ghost:hover {
  color: oklch(17% 0.01 65);
  text-decoration: underline;
  text-underline-offset: 4px;
}
.ds-btn-ghost:focus-visible {
  outline: 2px solid oklch(74% 0.175 65 / 50%);
  outline-offset: 2px;
}
.ds-btn-ghost:active {
  transform: scale(0.98);
}
@media (prefers-reduced-motion: reduce) {
  .ds-btn-ghost {
    transition-duration: 0.01ms;
  }
}

.ds-chip-language {
  display: inline-flex;
  align-items: center;
  padding: 2px 10px;
  background-color: oklch(80% 0.155 135 / 18%);
  color: oklch(80% 0.155 135);
  font-family: 'Albert Sans', ui-sans-serif, system-ui, sans-serif;
  font-size: 0.6875rem;
  font-weight: 600;
  border-radius: 9999px;
  flex-shrink: 0;
}

.ds-chip-status {
  display: inline-flex;
  align-items: center;
  padding: 2px 10px;
  background-color: oklch(92% 0.006 65);
  color: oklch(45% 0.014 65);
  font-family: 'Albert Sans', ui-sans-serif, system-ui, sans-serif;
  font-size: 0.6875rem;
  font-weight: 600;
  border-radius: 9999px;
  flex-shrink: 0;
}

.ds-input-select {
  padding: 10px 12px;
  background-color: oklch(95% 0.005 65);
  color: oklch(17% 0.01 65);
  font-family: 'Albert Sans', ui-sans-serif, system-ui, sans-serif;
  font-size: 0.875rem;
  font-weight: 500;
  border: 1px solid oklch(90% 0.008 65);
  border-radius: 8px;
  cursor: pointer;
  transition: border-color 150ms cubic-bezier(0.25, 1, 0.5, 1);
}
.ds-input-select:focus {
  outline: none;
  border-color: oklch(74% 0.175 65);
  box-shadow: 0 0 0 2px oklch(74% 0.175 65 / 50%);
}
@media (prefers-reduced-motion: reduce) {
  .ds-input-select {
    transition-duration: 0.01ms;
  }
}

.ds-card-callout {
  padding: 24px;
  background-color: oklch(74% 0.175 65);
  border-radius: 16px;
}
.ds-card-callout h2 {
  font-family: 'Bricolage Grotesque', ui-sans-serif, system-ui, sans-serif;
  font-size: clamp(1.4rem, 3vw + 0.3rem, 2.5rem);
  font-weight: 700;
  line-height: 0.9;
  letter-spacing: -0.025em;
  color: oklch(17% 0.01 65);
  margin: 0;
}
.ds-card-callout p {
  font-family: 'Albert Sans', ui-sans-serif, system-ui, sans-serif;
  font-size: 0.875rem;
  font-weight: 500;
  color: oklch(28% 0.08 65);
  max-width: 24rem;
  margin: 8px 0 0 0;
}
.ds-btn-callout {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 12px 16px;
  background-color: oklch(17% 0.01 65);
  color: oklch(99% 0.005 65);
  font-family: 'Albert Sans', ui-sans-serif, system-ui, sans-serif;
  font-size: 0.875rem;
  font-weight: 600;
  border: none;
  border-radius: 8px;
  text-decoration: none;
  cursor: pointer;
  transition: background-color 150ms cubic-bezier(0.25, 1, 0.5, 1);
  margin: 16px 8px 0 0;
}
.ds-btn-callout:hover {
  background-color: oklch(28% 0.01 65);
}
.ds-btn-callout:focus-visible {
  outline: 2px solid oklch(74% 0.175 65 / 50%);
  outline-offset: 2px;
}
.ds-btn-callout:active {
  transform: scale(0.98);
}
@media (min-width: 640px) {
  .ds-card-callout {
    padding: 32px;
  }
}
@media (prefers-reduced-motion: reduce) {
  .ds-btn-callout {
    transition-duration: 0.01ms;
  }
}

.ds-repo-item {
  display: block;
  padding: 16px 0;
  border-bottom: 1px solid oklch(90% 0.008 65);
  text-decoration: none;
  transition: background-color 150ms cubic-bezier(0.25, 1, 0.5, 1);
  margin: 0 -16px;
  padding-left: 16px;
  padding-right: 16px;
}
.ds-repo-item:hover {
  background-color: oklch(97% 0.005 65);
}
.ds-repo-item h3 {
  font-family: 'Albert Sans', ui-sans-serif, system-ui, sans-serif;
  font-size: 1rem;
  font-weight: 600;
  color: oklch(17% 0.01 65);
  transition: color 150ms cubic-bezier(0.25, 1, 0.5, 1);
  margin: 0;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.ds-repo-item:hover h3 {
  color: oklch(74% 0.175 65);
}
.ds-repo-item p {
  font-family: 'Albert Sans', ui-sans-serif, system-ui, sans-serif;
  font-size: 0.875rem;
  color: oklch(45% 0.014 65);
  margin: 4px 0 0 0;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
.ds-repo-item .ds-repo-stats {
  display: flex;
  align-items: center;
  gap: 16px;
  font-family: 'Albert Sans', ui-sans-serif, system-ui, sans-serif;
  font-size: 0.75rem;
  font-weight: 500;
  color: oklch(45% 0.014 65);
  flex-shrink: 0;
}
@media (min-width: 640px) {
  .ds-repo-item {
    padding: 20px 0;
    padding-left: 16px;
    padding-right: 16px;
  }
  .ds-repo-item h3 {
    font-size: 1rem;
  }
}
@media (prefers-reduced-motion: reduce) {
  .ds-repo-item,
  .ds-repo-item h3 {
    transition-duration: 0.01ms;
  }
}

.ds-tab-toggle {
  display: flex;
  gap: 4px;
  padding: 4px;
  background-color: oklch(92% 0.006 65);
  border-radius: 12px;
  width: fit-content;
}
.ds-tab-toggle button {
  padding: 10px 20px;
  font-family: 'Albert Sans', ui-sans-serif, system-ui, sans-serif;
  font-size: 0.875rem;
  font-weight: 600;
  border: none;
  border-radius: 8px;
  cursor: pointer;
  transition: color 150ms cubic-bezier(0.25, 1, 0.5, 1), background-color 150ms cubic-bezier(0.25, 1, 0.5, 1);
}
.ds-tab-active {
  background-color: oklch(99% 0.005 65);
  color: oklch(17% 0.01 65);
  box-shadow: 0 1px 3px oklch(0% 0 0 / 8%);
}
.ds-tab-inactive {
  background-color: transparent;
  color: oklch(45% 0.014 65);
}
.ds-tab-inactive:hover {
  color: oklch(17% 0.01 65);
}
.ds-tab-toggle button:focus-visible {
  outline: 2px solid oklch(74% 0.175 65 / 50%);
  outline-offset: -2px;
}
@media (min-width: 640px) {
  .ds-tab-toggle button {
    padding: 10px 20px;
  }
}
@media (prefers-reduced-motion: reduce) {
  .ds-tab-toggle button {
    transition-duration: 0.01ms;
  }
}

.ds-footer {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  justify-content: space-between;
  gap: 8px;
  padding: 16px;
  border-top: 1px solid oklch(90% 0.008 65);
  font-family: 'Albert Sans', ui-sans-serif, system-ui, sans-serif;
  font-size: 0.75rem;
  color: oklch(45% 0.014 65);
}
@media (min-width: 640px) {
  .ds-footer {
    flex-direction: row;
    align-items: center;
    max-width: 64rem;
    margin: 0 auto;
    padding: 16px 24px;
  }
}
